package demo

type User struct{ Name string }

func GetUser(id string) *User {
	return &User{Name: id}
}

files.handler.go:
package demo

func Handle(id string) string {
	u := GetUser(id)
	return u.Name
}

files.service.go:
package demo

func Service(ids []string) []string {
	var out []string
	for _, id := range ids {
		out = append(out, GetUser(id).Name)
	}
	return out
}

